    let caller_path = dir.join("Caller.kt");
    let alias_path = dir.join("Alias.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Group\n\nfun caller(): Int {\n    val group = Group()\n    return group.member.helper(1)\n}\n\nfun secondCaller(): Int {\n    val group = Group()\n    return group.member.helper(2)\n}\n",
    )
    .unwrap();
    fs::write(
        &alias_path,
        "package org.util\n\nclass Other {\n    fun helper(value: Int): Int = value\n}\ntypealias Helper = Other\nclass Group {\n    val member: Helper = Other()\n}\n",
    )
    .unwrap();

    // A property hop whose declared type is a type alias declared in an
    // explicitly imported package resolves the alias target in the alias's own
    // file and package scope before dispatching the trailing member across
    // packages.
    let helper_path = "org::util::Other::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
