fn traces_kotlin_cross_file_enum_companion_receiver_calls_in_live_workspace_and_persisted_index() {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let color_path = dir.join("Color.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Color\n\nfun caller(): Int {\n    Color.Factory.helper(1)\n    Color.Companion.helper(2)\n    return 0\n}\n",
    )
    .unwrap();
    fs::write(
        &color_path,
        "package org.util\n\nenum class Color {\n    companion object Factory {\n        fun helper(value: Int): Int = value\n    }\n    fun memberHelper(value: Int): Int = value\n}\n",
    )
    .unwrap();

    // An enum class declared in an explicitly imported package can host a
    // companion object, so both the declared-name and canonical `Companion`
    // spellings dispatch to the companion scope across packages.
    let helper_path = "org::util::Color::Companion::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::caller");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.indexed_files, 2);
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::caller");
}

